 "pillars": [
 {
 "id": "p1",
 "t": "الحنفية: المرئية وغير المرئية",
 "d": "النجاسة المرئية (ما يرى بعد الجفاف) يطهر محلها بزوال عينها ولو بغسلة واحدة على الصحيح ولو كانت غليظة، ولا يشترط تكرار الغسل، ويشترط زوال الطعم، ولا يضر بقاء لون يشق زواله ولا الريح. وعن أبي جعفر: مرتان بعد زوال العين، وعن فخر الإسلام: ثلاثاً. وغير المرئية: يغسل ثلاثاً وجوباً مع العصر كل مرة في ظاهر الرواية. وإن غسل في ماء جار أو صب عليه ماء كثير بحيث يخرج ما أصابه ويخلفه غيره ثلاثاً طهر بلا عصر.",
 "ref": "https://muslim-library.com/keoj/volume/29/19374/ و https://muslim-library.com/keoj/volume/29/19375/ و https://muslim-library.com/keoj/volume/29/19376/"
 },
 {
 "id": "p2",
 "t": "المالكية",
 "d": "يطهر المحل بغسله من غير تحديد عدد، بشرط زوال طعم النجاسة ولو عسر، ويشترط زوال اللون والريح إن تيسر. فإن تعسر لم يضر.",
 "ref": "https://muslim-library.com/keoj/volume/29/19376/"
 },
 {
 "id": "p3",
 "t": "الشافعية",
 "d": "إن كانت النجاسة عيناً وجبت إزالة الطعم ومحاولة إزالة اللون والريح. فإن عسر زوال الطعم بأن لم يزل بحت أو قرص ثلاث مرات عفي عنه ما دام العسر. ولا يضر بقاء لون أو ريح عسر زواله، فإن بقيا معاً ضر على الصحيح. وإن لم تكن عيناً (لا يدرك لها عين ولا وصف) كفى جري الماء عليها مرة.",
 "ref": "https://muslim-library.com/keoj/volume/29/19376/ و https://muslim-library.com/keoj/volume/29/19377/"
 },
 {
 "id": "p4",
 "t": "الحنابلة",
 "d": "تطهر المتنجسات بسبع غسلات منقية، لقول ابن عمر: أمرنا أن نغسل الأنجاس سبعاً (كما أوردته الموسوعة)، وألحقوا بنجاسة الكلب سائر النجاسات. ونقل البهوتي أن محل الاستنجاء يغسل سبعاً عند القاضي والشيرازي وابن عقيل، ونص أحمد في رواية أبي داود واختاره في المغني: لا يجب فيه عدد. ويضر بقاء الطعم، ويضر بقاء اللون أو الريح أو هما معاً إن تيسر زوالهما، فإن عسر لم يضر.",
 "ref": "https://muslim-library.com/keoj/volume/29/19377/"
 },
 {
 "id": "p5",
 "t": "غسالة المحل قبل أن يطهر",
 "d": "الغسالة المتغيرة بأحد أوصاف النجاسة نجسة، لحديث: إن الماء لا ينجسه شيء إلا ما غلب على ريحه ولونه وطعمه (كما أوردته الموسوعة). فينجس المحل الذي تصيبه، ويكون تطهيره كأي محل متنجس عند الجمهور. وتفصيل غير المتغيرة في جدول الخلاف.",
 "ref": "https://muslim-library.com/keoj/volume/29/19378/ و https://muslim-library.com/keoj/volume/29/19379/"
 },
 {
 "id": "p6",
 "t": "الجامد والمائع إذا وقعت فيه نجاسة",
 "d": "إذا وقعت النجاسة في جامد كالسمن الجامد رفعت وقور ما حولها وطرح والباقي طاهر. وإذا وقعت في مائع فإنه ينجس ولا يطهر عند جمهور الفقهاء ويراق. والحنفية يرون إمكان تطهيره بالغلي. وفي الحنابلة: أبو الخطاب يرى أن ما يتأتى تطهيره بالغلي كالزيت يطهر، وعند ابن قدامة والقاضي وابن عقيل لا يطهر غير الماء من المائعات إلا الزئبق.",
 "ref": "https://muslim-library.com/keoj/volume/29/19381/ و https://muslim-library.com/keoj/volume/29/19382/"
 },
 {
 "id": "p7",
 "t": "كيف تطهر الأرض بالماء",
 "d": "إذا تنجست الأرض بنجاسة مائعة كالبول والخمر فتطهيرها أن تغمر بالماء بحيث يذهب لون النجاسة وريحها، وما انفصل عنها غير متغير بها فهو طاهر. بهذا قال جمهور الفقهاء، لحديث الأعرابي. وإن أصابها ماء المطر أو السيول فغمرها وجرى عليها فهو كما لو صب عليها. فإن كان لا يزول لونها إلا بمشقة سقط ذلك كالثوب.",
 "ref": "https://muslim-library.com/keoj/volume/29/19389/ و https://muslim-library.com/keoj/volume/29/19390/"
 }
 ],
